local config = {
  ui_story_31030101_1_dialog_content = "Selalu ada suara teriakan aneh yang berasal dari kamar Eicy...",
  ui_story_31030101_2_dialog_content = "Jadi, hari ini aku akan mengumpulkan keberanian untuk menyelidiki...",
  ui_story_31030101_3_dialog_content = "Ada suara yang berasal dari kamarku, dan kamu mau tahu kenapa?",
  ui_story_31030101_4_dialog_content = "Ya, beberapa orang mengeluh soal suara yang berisik itu.",
  ui_story_31030101_5_dialog_content = "Sudah tugasku untuk memeriksanya.",
  ui_story_31030101_6_dialog_content = "Baiklah, kenapa kamu tidak masuk saja?",
  ui_story_31030101_7_dialog_content = "Oh! Tapi, kamu harus menutup matamu!",
  ui_story_31030101_8_dialog_content = "Kamu akan lebih mengerti setelah mengalaminya langsung.",
  ui_story_31030101_9_dialog_content = "Tidak—maksudku—aku hanya ingin kamu memberitahuku ada apa...",
  ui_story_31030101_10_dialog_content = "Jika tidak mengalaminya, bagaimana bisa kamu menjelaskannya kepada orang lain?",
  ui_story_31030101_11_dialog_content = "Oke... Aku harus memberanikan diri...",
  ui_story_31030101_12_dialog_content = "Baiklah, sepertinya sudah oke. Bagaimana rasanya, tidak bisa melihat? Kamu takut?",
  ui_story_31030101_13_option_content = "Tidak",
  ui_story_31030101_14_dialog_content = "Aku mungkin tak bisa melihat, tapi aku masih punya indra yang lain.",
  ui_story_31030101_15_dialog_content = "Aku bisa menebak di mana kamu berada dan bagaimana suasana di sekelilingku.",
  ui_story_31030101_16_option_content = "Sedikit",
  ui_story_31030101_17_dialog_content = "Aku tak tahu di mana aku! Aku merasa sebentar lagi akan menubruk sesuatu.",
  ui_story_31030101_18_dialog_content = "Aku akan memandumu. Jangan khawatir!",
  ui_story_31030101_19_dialog_content = "Lagi pula, kita sedang berada di Colossus-mu, jadi harusnya wilayah ini tak asing.",
  ui_story_31030101_20_dialog_content = "Terima kasih. Rasanya jadi sedikit lebih baik.",
  ui_story_31030101_21_dialog_content = "Kupikir-pikir, aku mengenalmu, dan aku mengenal area ini, jadi tak ada alasan untuk merasa gelisah.",
  ui_story_31030101_22_dialog_content = "Kita sampai! Silakan duduk.",
  ui_story_31030101_23_dialog_content = "Tak perlu gelisah. Mari mengobrol dulu.",
  ui_story_31030101_24_dialog_content = "Oke! Kamu bisa melepas penutup matanya sekarang.",
  ui_story_31030101_25_dialog_content = "Sekarang?",
  ui_story_31030101_26_dialog_content = "Astaga, cahaya itu terang! Dan di tempat lain gelap gulita!",
  ui_story_31030101_27_dialog_content = "Ini semua bagian dari pengalaman ini. Mari mulai sekarang. Duduklah.",
  ui_story_31030101_28_dialog_content = "Oke... Wow, bangku ini panjang sekali!",
  ui_story_31030101_29_dialog_content = "Aku membuatnya khusus. Jangan khawatir.",
  ui_story_31030101_30_dialog_content = "Cincin-cincin besi ini untuk apa?",
  ui_story_31030101_31_dialog_content = "Beberapa orang tidak duduk dengan kuat, jadi cincin itu untuk pengikat.",
  ui_story_31030101_32_dialog_content = "Pengikat apa?",
  ui_story_31030101_33_dialog_content = "Tunggu sebentar. Ada yang perlu kuambil.",
  ui_story_31030101_34_dialog_content = "Apa yang kamu lakukan? Ada suatu aroma yang <color=#FFB400>harum</color>, dan... <color=#FFB400>berasap</color>?",
  ui_story_31030101_35_dialog_content = "Jangan khawatir. Ini hanya bagian dari proses.",
  ui_story_31030101_36_dialog_content = "Aku... ingin pergi sekarang.",
  ui_story_31030101_37_dialog_content = "Kamu baru saja sampai. Apa maksudmu ingin pergi?",
  ui_story_31030101_38_dialog_content = "Oh, aku ingin bertanya kepadamu: bagaimana pendapatmu tentang pekerjaanmu sebagai Navigator?",
  ui_story_31030101_39_option_content = "Apa maksudmu?",
  ui_story_31030101_40_dialog_content = "Aku hanya ingin tahu apa pendapatmu tentang kinerjamu sendiri.",
  ui_story_31030101_41_dialog_content = "Semua orang bilang aku bisa sangat berguna dalam pertempuran...",
  ui_story_31030101_42_option_content = "Jadi, kurasa kinerjaku baik-baik saja?",
  ui_story_31030101_43_dialog_content = "Tapi, sebenarnya aku tak punya begitu banyak tanggung jawab.",
  ui_story_31030101_44_dialog_content = "Aku hanya mengemudikan Colossus dan mengurus tugas sehari-hari.",
  ui_story_31030101_45_dialog_content = "Bantuan yang kudapatkan sebenarnya lebih banyak dari yang kuberikan.",
  ui_story_31030101_46_dialog_content = "Ah, begitu.",
  ui_story_31030101_47_dialog_content = "Omong-omong, agak <color=#FFB400>panas</color> di sini...",
  ui_story_31030101_48_dialog_content = "Giliranku untuk bertanya. Jangan menyela!",
  ui_story_31030101_49_dialog_content = "Tahukah kamu kalau aku meminta Vice untuk menyediakan <color=#FFB400>ruang interogasi</color> untukku?",
  ui_story_31030101_50_option_content = "Ya.",
  ui_story_31030101_51_dialog_content = "Dia memang memberitahuku tentang itu, serta beberapa hal lainnya.",
  ui_story_31030101_52_option_content = "...",
  ui_story_31030101_53_dialog_content = "Kamu punya hak untuk tetap diam, tapi aku punya banyak cara untuk mendapatkan jawaban.",
  ui_story_31030101_54_dialog_content = "Maaf, menurutku percakapan ini berubah menjadi percakapan yang aneh.",
  ui_story_31030101_55_dialog_content = "Sebenarnya, aku sudah tahu kalau kamu mengerti.",
  ui_story_31030101_56_dialog_content = "Aku hanya bertanya untuk menilai reaksimu.",
  ui_story_31030101_57_dialog_content = "Apakah kamu yang memberi tahu Vice untuk menolak proposalku?",
  ui_story_31030101_58_option_content = "Ya",
  ui_story_31030101_59_dialog_content = "Tentu saja, Vice memiliki wewenangnya sendiri. Dia tak perlu persetujuanku untuk menolakmu.",
  ui_story_31030101_60_dialog_content = "Tapi dia sering meminta bantuanku jika merasa tertekan.",
  ui_story_31030101_61_dialog_content = "Seperti saat kamu terus bertanya padanya, \"Bisakah kita punya ruang interogasi?\"",
  ui_story_31030101_62_option_content = "Tidak",
  ui_story_31030101_63_dialog_content = "Begitu Vice mendengar proposalmu, insting pertamanya adalah menolak itu.",
  ui_story_31030101_64_dialog_content = "Jujur saja, proposalmu membuatnya sedikit takut.",
  ui_story_31030101_65_dialog_content = "Ah, jadi sepertinya kalian berdua berpikir aku ini berbahaya?",
  ui_story_31030101_66_dialog_content = "Oh, tidak. Aku benar-benar memercayaimu.",
  ui_story_31030101_67_dialog_content = "Jadi, itu sebabnya kamu dengan bodohnya setuju untuk mengikutiku ke sini...",
  ui_story_31030101_68_dialog_content = "Ini mungkin Colossus-mu, tapi kita sedang berada di ruangan tertutup.",
  ui_story_31030101_69_dialog_content = "Kamu tak takut dengan apa yang bisa kulakukan padamu di sini?",
  ui_story_31030101_70_option_content = "Ya",
  ui_story_31030101_71_dialog_content = "Memiliki rasa takut yang sehat akan hal yang tak diketahui itu baik.",
  ui_story_31030101_72_dialog_content = "Tapi kamu tak terlihat takut sama sekali.",
  ui_story_31030101_73_option_content = "Tidak",
  ui_story_31030101_74_dialog_content = "Aku sudah menduga aku akan diinterogasi olehmu setelah datang kemari.",
  ui_story_31030101_75_dialog_content = "Tapi bagaimanapun juga, kita masih berada di Colossus milikku.",
  ui_story_31030101_76_dialog_content = "Aku bisa mengontrol Soroz dari jarak jauh dan bahkan membuat Soroz berputar-putar di udara.",
  ui_story_31030101_77_dialog_content = "Kamu ingin mencoba itu?",
  ui_story_31030101_78_dialog_content = "Hehe, tatapanmu yang mengintimidasi itu menyenangkan, tapi...",
  ui_story_31030101_79_dialog_content = "Aku tidak sedang menginterogasimu.",
  ui_story_31030101_80_dialog_content = "Panas, kursi yang aneh, asap yang ganjil...",
  ui_story_31030101_81_dialog_content = "Sudah pasti ini <color=#FFB400>ruang interogasi</color>!",
  ui_story_31030101_82_dialog_content = "Aku tahu kamu punya segala macam alat interogasi tersembunyi di sini!",
  ui_story_31030101_83_dialog_content = "Ya, seperti katamu, aku memang mengubah tempat ini menjadi ruang interogasi. Kamu ingin melihatnya?",
  ui_story_31030101_84_dialog_content = "*Menyalakan lampu*",
  ui_story_31030101_85_dialog_content = "Aha! Ini—",
  ui_story_31030101_86_dialog_content = "—hanya ruangan biasa?",
  ui_story_31030101_87_dialog_content = "Yep.",
  ui_story_31030101_88_dialog_content = "Apa itu yang ada di sudut?",
  ui_story_31030101_89_dialog_content = "Itu diffuser. Ada alat penghangat di dalamnya.",
  ui_story_31030101_90_dialog_content = "Aku menambahkan minyak esensial aromatik juga. Bagaimana menurutmu? Ruangan ini jadi terasa sedikit nyaman, 'kan?",
  ui_story_31030101_91_dialog_content = "Nyaman? Untuk interogasi? Itu yang akan kamu lakukan di sini, 'kan? Menginterogasi orang?",
  ui_story_31030101_92_dialog_content = "Tidak.",
  ui_story_31030101_93_dialog_content = "Tapi bukankah kamu baru saja menginterogasiku?",
  ui_story_31030101_94_dialog_content = "Kamu menyebut itu interogasi?",
  ui_story_31030101_95_dialog_content = "Lalu kenapa aku selalu mendengar suara teriakan dari ruanganmu?",
  ui_story_31030101_96_dialog_content = "Itu karena <size=40>Taijutsuku</size> yang kuat!",
  ui_story_31030101_97_dialog_content = "Hmm? Apa maksudmu?",
  ui_story_31030101_98_dialog_content = "Apakah punggungmu terasa sakit akhir-akhir ini?",
  ui_story_31030101_99_dialog_content = "Hmm? Aku...",
  ui_story_31030101_100_dialog_content = "Berbaring! Sekarang! Di bangku!",
  ui_story_31030101_101_dialog_content = "Tunggu! Sudah cukup! Kenapa kamu memborgolku ke bangku?!",
  ui_story_31030101_102_dialog_content = "Aku akan berteriak minta tolong! Aku akan...",
  ui_story_31030101_103_dialog_content = "Hei!",
  ui_story_31030101_104_dialog_content = "<size=40>Ah</size><size=45>!</size>",
  ui_story_31030101_105_dialog_content = "<size=45>Oh!</size>",
  ui_story_31030101_106_dialog_content = "<size=50>Aduh</size><size=55>!</size>",
  ui_story_31030101_107_dialog_content = "<size=55>Rasakan itu!</size>",
  ui_story_31030101_108_dialog_content = "Jangan terlalu keras! Tolong, jangan terlalu keras!",
  ui_story_31030101_109_dialog_content = "<size=40>Hei! Aduh—hentikan!</size>",
  ui_story_31030101_110_dialog_content = "Aku bahkan belum memijat. Ada apa, tak kuat, ya?",
  ui_story_31030101_111_dialog_content = "Oke, aku menyerah! Aku hanya ingin tahu suara apa itu...",
  ui_story_31030101_112_dialog_content = "Itu karena... kamu <color=#FFB400>memijat</color> orang-orang?",
  ui_story_31030101_113_dialog_content = "Itu salah satu kegunaan Taijutsu!",
  ui_story_31030101_114_dialog_content = "Dengan serangkaian \"serangan\" ringan pada tubuh, aku bisa meringankan segala macam rasa sakit dan nyeri.",
  ui_story_31030101_115_dialog_content = "Kukira kamu menginterogasi orang-orang di sini! <size=25>Dengan semacam minyak esensial beraroma Taijutsu atau apalah...</size>",
  ui_story_31030101_116_dialog_content = "Aku ini interogator profesional. Kamu kira aku akan menanyai orang yang tak bersalah?",
  ui_story_31030101_117_dialog_content = "Aku hanya membawa orang ke sini untuk mengobrol dan meredakan rasa cemas mereka.",
  ui_story_31030101_118_dialog_content = "Lagi pula, jika aku ingin menginterogasimu...",
  ui_story_31030101_119_dialog_content = "Aku hanya perlu menatapmu dengan <color=#FFB400>mata kananku</color>...",
  ui_story_31030601_1_dialog_content = "Matahari menyengat seperti penyiksa yang kejam.",
  ui_story_31030601_2_dialog_content = "Silaunya cukup panas untuk menggosongkan kulit.",
  ui_story_31030601_3_dialog_content = "Lonjakan ombak yang dapat menenggelamkan satu pasukan.",
  ui_story_31030601_4_dialog_content = "Sementara Eclipsite yang gelisah mengintai dalam bayangan.",
  ui_story_31030601_5_dialog_content = "Ah, indahnya musim panas.",
  ui_story_31030601_6_dialog_content = "Tentu saja, ada <color=#FFB400>dirimu yang tua dan mujur</color>—",
  ui_story_31030601_7_dialog_content = "Kamu memang lihat bermain kata... Meski saat kamu mengucapkannya, itu tak terdengar seperti hari libur yang menyenangkan...",
  ui_story_31030601_8_dialog_content = "Lagi pula, memangnya aku mujur?",
  ui_story_31030601_9_dialog_content = "Diseret untuk pergi belanja di siang bolong saat matahari sedang panas-panasnya...",
  ui_story_31030601_10_dialog_content = "Bahkan bisa-bisanya kamu mengharapkanku untuk membawa semua barang ini...?",
  ui_story_31030601_11_dialog_content = "PlayerName yang malang... Keringatmu bercucuran.",
  ui_story_31030601_12_dialog_content = "Sepertinya cukup untuk hari ini.",
  ui_story_31030601_13_dialog_content = "Sungguh!?",
  ui_story_31030601_14_dialog_content = "Tentu saja belum! Masih ada satu toko lagi!",
  ui_story_31030601_15_dialog_content = "Ayo segera ke sana!",
  ui_story_31030601_16_dialog_content = "Tunggu sebentar, Eicy! Berhenti menyeret-nyeretku! Aku tidak bisa bergerak secepat itu!",
  ui_story_31030601_17_dialog_content = "(Di suatu buku yang pernah aku baca, tertulis bahwa musim panas selalu disertai dengan keringat dan air mata.)",
  ui_story_31030601_18_dialog_content = "(Perpaduan getir itu mungkin cara yang sempurna untuk menggambarkan kesulitanku saat ini.)",
  ui_story_31030601_19_dialog_content = "(Awalnya, kukira Eicy hanya ingin aku membantunya membawakan <color=#FFB400>beberapa</color> barang.)",
  ui_story_31030601_20_dialog_content = "(Pada waktu itu, aku tidak menyadari apa yang akan menantiku...)",
  ui_story_31030601_21_dialog_content = "Ah...",
  ui_story_31030601_22_dialog_content = "Ah, PlayerName...",
  ui_story_31030601_23_dialog_content = "Ada apa, Eicy? Kamu tampak murung...",
  ui_story_31030601_24_dialog_content = "Kenapa? Kamu mau menghiburku?",
  ui_story_31030601_25_dialog_content = "Omong-omong, tujuan utama berlibur itu untuk bersantai, jadi bagaimana kalau kita bersenang-senang?",
  ui_story_31030601_26_dialog_content = "Hei, PlayerName... Apa pendapatmu tentang musim panas?",
  ui_story_31030601_27_option_content = "Matahari, laut, pasir, dan keindahan!",
  ui_story_31030601_28_dialog_content = "Kamu benar!",
  ui_story_31030601_29_dialog_content = "Matahari menyinari dunia, memberikan semangat pada semua yang disentuhnya.",
  ui_story_31030601_30_dialog_content = "Namun, hal yang terlahir dari pemandangan mewah ini tak sesederhana itu.",
  ui_story_31030601_31_option_content = "Mendidih, tandus, dangkal, dan membosankan?",
  ui_story_31030601_32_dialog_content = "Kamu tidak suka musim panas, PlayerName?",
  ui_story_31030601_33_dialog_content = "Ada ratusan kegiatan seru untuk dinikmati di pantai, gulungan ombak untuk bersenda gurau, dan sinar matahari musim panas yang cerah untuk berjemur.",
  ui_story_31030601_34_dialog_content = "Atau mungkin...",
  ui_story_31030601_35_dialog_content = "Mungkin kamu sudah memahami kebenaran di balik semua ini, PlayerName?",
  ui_story_31030601_36_dialog_content = "Alam adalah algojo terhebat.",
  ui_story_31030601_37_dialog_content = "Di bawah sinar matahari yang cerah, terbentang dataran yang ganas dan tak mengenal hukum, di bawah ombak yang riuh terbentang laut yang dalam, yang mampu menelan segalanya.",
  ui_story_31030601_38_dialog_content = "Bahkan saat ini, samar-samar kudengar seseorang menjerit di bawah teriknya matahari.",
  ui_story_31030601_39_dialog_content = "Victoria bilang ini juga bagian dari pesona musim panas!",
  ui_story_31030601_40_dialog_content = "Namun, sebagai kaki tangan alam, aku hadir bukan untuk dihukum.",
  ui_story_31030601_41_dialog_content = "Jadi?",
  ui_story_31030601_42_dialog_content = "Jadi, berbelanjalah denganku! Kita harus membeli beberapa kebutuhan musim panas!",
  ui_story_31030601_43_dialog_content = "Kipas angin berdaya Lumina, payung, semprotan air pelembap, dan banyak kebutuhan lainnya... Aku paham kalau kamu mau membelinya, tapi masing-masing ada sepuluh? Yang benar saja!",
  ui_story_31030601_44_dialog_content = "Ini, sih, bukan sekadar kebutuhan... Sebaiknya kamu beli setoko-tokonya!",
  ui_story_31030601_45_dialog_content = "Namun, itu masih belum cukup! Kebutuhan yang utama belum dibeli!",
  ui_story_31030601_46_dialog_content = "Yaitu—",
  ui_story_31030601_47_dialog_content = "<color=#FFB400>Baju renangku!</color>",
  ui_story_31030601_48_dialog_content = "Toko baju renang tersohor di pantai ini bernama <color=#FFB400>Diamond Rhythm</color>.",
  ui_story_31030601_49_dialog_content = "Toko itu menjual segala jenis pakaian renang kelas atas yang dijahit dengan tangan dan rumit! Kita akan menemukannya di sana!",
  ui_story_31030601_50_dialog_content = "Aku akan mencari baju renang yang sempurna... ada banyak sekali pilihannya! Ini akan menjadi tantangan.",
  ui_story_31030601_51_dialog_content = "Apakah dunia sungguh membutuhkan begitu banyak jenis pakaian renang!?",
  ui_story_31030601_52_dialog_content = "Pakaian renang sepinggang, pakaian renang gaya terpisah, pakaian renang one-piece... Omong-omong, bahkan pakaian renang pria punya gaya yang berbeda, tahu?",
  ui_story_31030601_53_dialog_content = "Namun, dari begitu banyak jenis, pasti sulit memilihnya. Apakah ada gaya atau tipe tertentu yang kamu suka?",
  ui_story_31030601_54_dialog_content = "Gaya dan tipe favoritku?",
  ui_story_31030601_55_dialog_content = "Hollow Gaze?",
  ui_story_31030601_56_dialog_content = "Yang itu berfitur penglihatan 360°?",
  ui_story_31030601_57_dialog_content = "Benar! Mari lihat apa yang dipilihkan Hollow Gaze untuk kita!",
  ui_story_31030601_58_dialog_content = "Ah, celana renang ini... Lalu rok hitam kecil ini seperti sepasang sayap!",
  ui_story_31030601_59_dialog_content = "Itu baru Hollow Gaze. Sungguh menambah wawasan.",
  ui_story_31030601_60_dialog_content = "Yang ini bagus juga... Yang ini juga!",
  ui_story_31030601_61_dialog_content = "Yang ini... dan ini!",
  ui_story_31030601_62_dialog_content = "Tunggu sebentar... Kamu tidak akan membeli semuanya, 'kan?",
  ui_story_31030601_63_dialog_content = "Hah? Tentu saja aku akan membeli semuanya! Aku menyukainya!",
  ui_story_31030601_64_dialog_content = "Hei! Tolong bungkus yang ini!",
  ui_story_31030601_65_dialog_content = "Semua ini!? Bukankah ini harganya bisa menghabiskan seluruh tabunganmu?",
  ui_story_31030601_66_dialog_content = "Jangan khawatir. Uang bukan masalah bagiku.",
  ui_story_31030601_67_dialog_content = "Selain itu, jika tidak bisa menghabiskan uang untuk hal-hal yang kusuka, aku harus belanja apa, dong!?",
  ui_story_31030601_68_dialog_content = "Meski membuat kantongku kempis, belanjaanku ini mengisi hatiku dengan sukacita.",
  ui_story_31030601_69_dialog_content = "Wah! Syal halus ini juga tampak bagus!",
  ui_story_31030601_70_dialog_content = "Namun, aku masih belum merasa puas... Mungkin aku harus membeli beberapa lagi...",
  ui_story_31030601_71_dialog_content = "Apa?",
  ui_story_31030601_72_dialog_content = "Ah...",
  ui_story_31030601_73_dialog_content = "Omong-omong, bagaimana kalau aku mencoba baju renang baru dulu?",
  ui_story_31030601_74_dialog_content = "(Eicy terlihat sangat senang... Namun, kenapa dia masih berdesah...?)",
  ui_story_31030601_75_dialog_content = "(Hmm... Hah? Kacamata hitam ini...)",
  ui_story_31030601_76_dialog_content = "Sebelah sini, PlayerName!",
  ui_story_31030601_77_dialog_content = "Ta-ra! Bagaimana menurutmu?",
  ui_story_31030601_78_option_content = "Terlihat luar biasa!",
  ui_story_31030601_79_dialog_content = "Hitam dan emas memang sangat cocok—mewah dan mulia, seperti kamu!",
  ui_story_31030601_80_dialog_content = "Syal halus itu adalah sebuah karya seni.",
  ui_story_31030601_81_option_content = "Seolah-olah jantungku berhenti berdetak!",
  ui_story_31030601_82_dialog_content = "Ini benar-benar berbeda dari gayamu yang biasa, Eicy!",
  ui_story_31030601_83_dialog_content = "Aksesori logam itu sangat cocok untukmu, Eicy!",
  ui_story_31030601_84_dialog_content = "Heehee! Aku tidak percaya aku benar-benar dipuji oleh PlayerName...",
  ui_story_31030601_85_dialog_content = "Sudah diputuskan! Pakaian renang ini, serta setumpuk barang dari sebelumnya.",
  ui_story_31030601_86_dialog_content = "Kita hanya memilih dua pertiga dari stok toko ini... Lumayan!",
  ui_story_31030601_87_dialog_content = "Akhirnya, saatnya membayar!",
  ui_story_31030601_88_dialog_content = "Silakan bayar di sini... Totalnya <color=#FFB400>lima juta Nightium</color>.",
  ui_story_31030601_89_dialog_content = "(Banyak sekali belanjaannya! Eicy jauh lebih kaya daripada penampilannya.)",
  ui_story_31030601_90_dialog_content = "(Kuharap kami bisa sekaya dia suatu hari nanti...)",
  ui_story_31030601_91_dialog_content = "Kamu ingin membeli barang yang dipegang temanmu?",
  ui_story_31030601_92_dialog_content = "Ah, tentu saja!",
  ui_story_31030601_93_dialog_content = "PlayerName, kamu mau sedikit memanjakan dirimu juga?",
  ui_story_31030601_94_dialog_content = "Tidak, ini untukmu.",
  ui_story_31030601_95_dialog_content = "Ini Nightium-nya.",
  ui_story_31030601_96_dialog_content = "Terima kasih.",
  ui_story_31030601_97_dialog_content = "Kenapa kamu tidak beli sesuatu untukmu sendiri?",
  ui_story_31030601_98_dialog_content = "Hah?",
  ui_story_31030601_99_dialog_content = "Kamu tampak sedikit muram... jadi kupikir aku akan memberimu hadiah kecil.",
  ui_story_31030601_100_dialog_content = "Semoga bisa sedikit menghiburmu.",
  ui_story_31030601_101_dialog_content = "Ini adalah sebuah <color=#FFB400>kacamata hitam</color>. Kurasa benar-benar cocok untukmu. Juga cocok dengan baju renang yang kamu coba barusan.",
  ui_story_31030601_102_dialog_content = "Oh!",
  ui_story_31030601_103_dialog_content = "Mau mencobanya?",
  ui_story_31030601_104_dialog_content = "Boleh?",
  ui_story_31030601_105_dialog_content = "Sepertinya kacamata ini ditakdirkan untukmu, Madam!",
  ui_story_31030601_106_dialog_content = "Baiklah, aku sudah dapat semuanya! Ayo pulang, Eicy!",
  ui_story_31030601_107_dialog_content = "Ah! Eh... Oke...",
  ui_story_31030601_108_dialog_content = "...",
  ui_story_31030601_109_dialog_content = "...",
  ui_story_31030601_110_dialog_content = "Eicy, bolehkah aku bertanya?",
  ui_story_31030601_111_dialog_content = "Kamu tiba-tiba jadi pendiam. Kamu tidak suka hadiahku?",
  ui_story_31030601_112_dialog_content = "Tidak! Aku hanya sedang memikirkan sesuatu...",
  ui_story_31030601_113_dialog_content = "Kamu mau tahu kenapa aku merasa sedih hari ini?",
  ui_story_31030601_X113_dialog_content = "Yah... Tentu saja itu bukan karena hadiahmu!",
  ui_story_31030601_114_dialog_content = "Ini karena...",
  ui_story_31030601_X114_dialog_content = "Aku merasa seperti... ada yang salah denganku. Seolah-olah ada <color=#FFB400>sesuatu yang hilang</color>.",
  ui_story_31030601_115_dialog_content = "Hah? Apa maksudmu?",
  ui_story_31030601_116_dialog_content = "Aku bisa melihat ketakutan orang lain dengan Hollow Gaze milikku.",
  ui_story_31030601_117_dialog_content = "Setiap kali melihat rasa takut mereka, aku juga bisa melihat emosi yang rumit di dalam hati mereka.",
  ui_story_31030601_118_dialog_content = "Namun, aku juga mengalami rasa sakit yang hebat, tetapi aku tidak merasakan emosi yang kuat seperti itu.",
  ui_story_31030601_119_dialog_content = "Rasanya seolah-olah... Aku berbeda dari orang lain.",
  ui_story_31030601_120_dialog_content = "Hmm...",
  ui_story_31030601_121_dialog_content = "Bukan itu saja.",
  ui_story_31030601_122_dialog_content = "Pekerjaanku dengan True Order tidak berjalan mulus. Ketika aku kembali, kondisiku sangat buruk.",
  ui_story_31030601_123_dialog_content = "Meski Victoria menghiasi kepalaku dengan sentuhannya, dia tidak mengatakan sepatah kata pun, dia juga jelas tidak memujiku.",
  ui_story_31030601_124_dialog_content = "Nails dan Faust begitu menyebalkan... Mereka selalu ada di sisi Victoria...",
  ui_story_31030601_125_dialog_content = "Pada dasarnya, aku sedang mengalami banyak tekanan, jadi aku datang ke pantai untuk bersantai.",
  ui_story_31030601_126_dialog_content = "(Eicy selalu tampak sangat bahagia... Siapa sangka hal-hal kecil seperti itu membuatnya banyak pikiran?)",
  ui_story_31030601_127_dialog_content = "Itu sebabnya aku ingin pergi <color=#FFB400>berbelanja</color>—untuk melupakan kekhawatiranku dengan sedikit terapi belanja.",
  ui_story_31030601_128_dialog_content = "Namun, tidak selalu berhasil.",
  ui_story_31030601_129_dialog_content = "Namun, saat kamu memberiku kacamata hitam itu...",
  ui_story_31030601_130_dialog_content = "Semua masalah di hatiku hilang.",
  ui_story_31030601_131_dialog_content = "Rasanya seperti setelah hujan, saat yang tersisa hanyalah kejernihan dan kedamaian.",
  ui_story_31030601_132_dialog_content = "Jadi, aku mulai berpikir—kenapa hadiahmu memiliki keajaiban seperti itu?",
  ui_story_31030601_133_dialog_content = "Magic?",
  ui_story_31030601_134_dialog_content = "Kini, akhirnya aku menemukan jawabannya!",
  ui_story_31030601_135_dialog_content = "Tunggu di sini sebentar! Aku akan segera kembali!",
  ui_story_31030601_136_dialog_content = "Apa!? Untuk apa semua makanan penutup ini? Juga semua es serut ini!?",
  ui_story_31030601_137_dialog_content = "Hei, ini semuanya untukmu! Aku membeli semua makanan penutup dan es serut dari kios es serut di sana!",
  ui_story_31030601_138_dialog_content = "Apa? Kamu kehabisan es serut!?",
  ui_story_31030601_139_dialog_content = "Ya, maaf...",
  ui_story_31030601_140_dialog_content = "Aku datang jauh-jauh dari Rediesel Desert, dan bahkan tidak bisa mendapatkan es serut!?",
  ui_story_31030601_141_dialog_content = "Melalui angin, pasir, badai hujan, petir, dan kilat—segala macam!",
  ui_story_31030601_142_dialog_content = "Semua itu demi menikmati es serut di tepi pantai!",
  ui_story_31030601_143_dialog_content = "Namun, setiap hari ketika aku tiba di sini, es serutmu sudah habis!",
  ui_story_31030601_144_dialog_content = "Kamu tahu betapa aku telah menderita selama tiga hari terakhir ini!?",
  ui_story_31030601_145_dialog_content = "Aku benar-benar minta maaf.",
  ui_story_31030601_146_dialog_content = "(Aku tidak menyangka kios es serutku akan terbukti sangat populer...)",
  ui_story_31030601_147_dialog_content = "Bukan itu saja—aku ingin memberimu semua yang kami beli saat pesta belanja hari ini.",
  ui_story_31030601_148_dialog_content = "A-apa? Tidak... Aku baru saja memberimu kacamata hitam!",
  ui_story_31030601_149_dialog_content = "Barang-barang ini terlalu mahal untuk aku terima.",
  ui_story_31030601_150_dialog_content = "Tentu, harganya mahal, tetapi di hatiku, semuanya setara dengan <color=#FFB400>nilai kacamata hitam itu</color>.",
  ui_story_31030601_151_dialog_content = "Biar kujelaskan...",
  ui_story_31030601_152_dialog_content = "Dalam hal perdagangan, tentu saja, aku yakin kamu harus mendapatkan apa yang kamu bayar.",
  ui_story_31030601_153_dialog_content = "Namun, <color=#FFB400>hadiah</color> yang kamu berikan padaku... <color=#FFB400>Hadiah</color> itu <color=#FFB400>tak ternilai</color>...",
  ui_story_31030601_154_dialog_content = "Hadiahmu telah memberiku kebahagiaan lebih besar daripada semua barang yang kita beli sepanjang hari.",
  ui_story_31030601_155_dialog_content = "Sejujurnya, ini masih belum cukup... Jadi, hanya ini yang bisa kutawarkan untuk membalasmu atas hadiahmu yang tak ternilai.",
  ui_story_31030601_156_dialog_content = "Kamu tinggal menerimanya saja.",
  ui_story_31030601_157_dialog_content = "Sekarang aku merasa hadiahmu lebih menyentuh ketimbang hadiahku...",
  ui_story_31030601_158_dialog_content = "Terima kasih, Eicy. Terima kasih telah menghargai hadiahku seperti ini.",
  ui_story_31030601_159_dialog_content = "Namun, aku benar-benar tidak membutuhkannya! Mengetahui perasaanmu sudah cukup bagiku!",
  ui_story_31030601_160_dialog_content = "Jadi, begitulah perasaanmu, PlayerName...",
  ui_story_31030601_161_dialog_content = "Ya!",
  ui_story_31030601_162_dialog_content = "Yah, itu tidak akan berhasil sama sekali.",
  ui_story_31030601_163_dialog_content = "Hah?",
  ui_story_31030601_164_dialog_content = "Aku akan memakai kacamata hitam pemberianmu, tetapi aku juga ingin kamu menghargai hadiahku, PlayerName!",
  ui_story_31030601_165_dialog_content = "Kamu harus membawa semua yang kubeli ke Colossus... dan kamu harus menghabiskan semua makanan penutup yang kuberikan!",
  ui_story_31030601_166_dialog_content = "Itu berarti sorbet, milkshake stroberi, es krim cokelat, dan bahkan seporsi makan siang ubur-ubur dan nasi!",
  ui_story_31030601_167_dialog_content = "(Bagaimana bisa ada ubur-ubur tercampur di sana!?)",
  ui_story_31030601_168_dialog_content = "Tidak... Ini terlalu berlebihan...",
  ui_story_31030601_169_dialog_content = "Eicy, aku benar-benar tidak bisa menghabiskan semua ini!",
  ui_story_31030601_170_dialog_content = "Hei! Kamu bahkan belum menggigitnya sedikit pun!",
  ui_story_31030601_171_dialog_content = "Oh, aku paham!",
  ui_story_31030601_172_dialog_content = "Kamu pasti ingin aku menyuapimu, 'kan? PlayerName?",
  ui_story_31030601_173_dialog_content = "Jangan khawatir! Aku di sini untuk memuaskan semua fantasi terliarmu, PlayerName!",
  ui_story_31030601_174_dialog_content = "Buka mulutmu lebar-lebar, PlayerName—",
  ui_story_31030601_175_dialog_content = "Tidak! Tidak! Tidaaaaak!",
  ui_story_31030601_176_dialog_content = "Hampir saja!",
  ui_story_31030601_177_dialog_content = "Pastikan kamu makan semuanya—sampai—habis!",
  ui_story_31030601_178_dialog_content = "Sorbet, potongan buah, dan bahkan saus rasberi! Jangan sisakan sedikit pun!",
  ui_story_31030601_179_dialog_content = "Jangan pernah berpikir juga untuk meludahkannya!",
  ui_story_31030601_180_dialog_content = "Hollow Gaze milikku mengawasimu!",
  ui_story_31030601_181_dialog_content = "Eh...",
  ui_story_31030601_182_dialog_content = "(Aku merasa perutku yang kosong ini akan memberontak nanti...)",
  ui_story_31030601_183_dialog_content = "(Apakah ada cara agar aku bisa keluar dari ini?)",
  ui_story_31030601_184_dialog_content = "(Aku terus memikirkan kata-kata dalam buku itu. \"Musim panas selalu disertai dengan keringat dan air mata...\")",
  ui_story_31030601_185_dialog_content = "(Perpaduan getir itu mungkin cara yang sempurna untuk menggambarkan kesulitanku saat ini.)",
  ui_story_31030601_186_dialog_content = "(Eicy sendiri memberiku sesendok...)",
  ui_story_31030601_187_dialog_content = "(Ini adalah kesengsaraan manis bercampur pahit paling romantis yang pernah ada...)",
  ui_story_31030602_1_dialog_content = "(Saya bersumpah akan selalu memeriksa persediaan kami sebelum setiap penerbangan.)",
  ui_story_31030602_2_dialog_content = "(Saya akan memastikan saya tidak perlu berhenti di antah berantah untuk persediaan lagi.)",
  ui_story_31030602_3_dialog_content = "(Saya dalam pelarian sekarang.)",
  ui_story_31030602_4_dialog_content = "(Saya sedang diburu, dan saya tidak bisa mengatakan dengan pasti apakah itu Aurorian atau bukan.)",
  ui_story_31030602_5_dialog_content = "(Aku lapar, haus, dan sangat lelah... Segala sesuatu di sekitarku terasa begitu gelap dan tanpa harapan.)",
  ui_story_31030602_6_dialog_content = "(Saya tidak memiliki harapan untuk keselamatan di kota yang aneh ini.)",
  ui_story_31030602_7_dialog_content = "(Terlepas dari apa yang akan terjadi selanjutnya, yang bisa saya lakukan sekarang adalah lari.)",
  ui_story_31030602_8_dialog_content = "(Kalau saja aku tidak datang ke kota ini setengah jam yang lalu—)",
  ui_story_31030602_9_dialog_content = "Oh syukurlah, sebuah kota! Saya akhirnya bisa membeli beberapa persediaan!",
  ui_story_31030602_10_dialog_content = "Fiuh, kakiku pegal sekali... Aku ingin istirahat, tapi aku harus mencari toko dulu.",
  ui_story_31030602_11_dialog_content = "Saya pikir saya mendengar beberapa orang di sana. Aku harus pergi bertanya kepada mereka.",
  ui_story_31030602_12_dialog_content = "Halo! Maafkan aku, tapi...",
  ui_story_31030602_13_dialog_content = "Ssst! Ada kekacauan dan kebingungan di tempat ini...",
  ui_story_31030602_14_dialog_content = "Hah? Apa yang terjadi disini?",
  ui_story_31030602_15_dialog_content = "Dolly saya hanya memiliki satu mata. Kemana perginya yang lain?",
  ui_story_31030602_16_dialog_content = "A-Apakah kamu baik-baik saja?",
  ui_story_31030602_17_dialog_content = "Jari-jarimu sangat cantik, aku menginginkannya, biarkan aku memilikinya...",
  ui_story_31030602_18_dialog_content = "Bwah! A-Apa yang kau bicarakan?!",
  ui_story_31030602_19_dialog_content = "Tetap, tetap ...",
  ui_story_31030602_20_dialog_content = "Saya akhirnya kehilangan mereka. Apa yang salah dengan orang-orang ini? Mereka sangat aneh.",
  ui_story_31030602_21_dialog_content = "Di situ kau rupanya.",
  ui_story_31030602_22_dialog_content = "Hah? Anda tahu saya?",
  ui_story_31030602_23_dialog_content = "Bau darah yang murni dan tidak ternoda. Betapa menyenangkan!",
  ui_story_31030602_24_dialog_content = "Ahh! Menjauh dari saya!",
  ui_story_31030602_25_dialog_content = "Oh, betapa sakitnya! Ayo, bergabunglah denganku di jurang!",
  ui_story_31030602_26_dialog_content = "Apa? TIDAK! Tetap kembali!",
  ui_story_31030602_27_dialog_content = "Inilah akhir... akhir hidup kita! <size=50>Mari kita akhiri semuanya!</size>",
  ui_story_31030602_28_dialog_content = "Jenis apa <size=45>raksasa</size> apakah kamu?! Heeeeelp!",
  ui_story_31030602_29_dialog_content = "Huff-puff... Aku... aku tidak bisa lari lagi...",
  ui_story_31030602_30_dialog_content = "Heeheehee! Tidak ada jalan keluar!",
  ui_story_31030602_31_dialog_content = "(Tidak peduli apa, saya tidak bisa berhenti! Yang bisa saya lakukan sekarang adalah lari!)",
  ui_story_31030602_32_dialog_content = "<color=#e8d9bb>Gedebuk-</color>",
  ui_story_31030602_33_dialog_content = "Ahhh! Aku tersandung batu!",
  ui_story_31030602_34_dialog_content = "Heeheehee! Aku datang untuk menjemputmu!",
  ui_story_31030602_35_dialog_content = "PlayerName? Sedang apa kamu di sini?",
  ui_story_31030602_36_dialog_content = "Eicy! Tolong aku!",
  ui_story_31030602_37_dialog_content = "Apa? Duduk saja dan istirahatlah jika kau lelah, aku sedang mencari sesuatu.",
  ui_story_31030602_38_dialog_content = "Hai! Kembali!",
  ui_story_31030602_39_dialog_content = "Heeheehee! Saya pikir saya akan membawa pulang kaki Anda dan menyimpannya untuk nanti!",
  ui_story_31030602_40_dialog_content = "G-Pergi dariku, dasar gila!",
  ui_story_31030602_41_dialog_content = "Ah! Kena kau!",
  ui_story_31030602_42_dialog_content = "Sempurna! Saya belum pernah melihat Anda sebelumnya, yang berarti saya belum menanyakan apa pun kepada Anda!",
  ui_story_31030602_43_dialog_content = "Agh...Nng...",
  ui_story_31030602_44_dialog_content = "Mari kita mulai interogasi!",
  ui_story_31030602_45_dialog_content = "Memutar... keinginan...",
  ui_story_31030602_46_dialog_content = "Katakan padaku, apakah kamu melihat seorang pria membawa buku tebal di sekitar sini baru-baru ini?",
  ui_story_31030602_47_dialog_content = "Buku... bung...",
  ui_story_31030602_48_dialog_content = "Itu benar! Pernahkah kamu melihatnya? Cobalah yang terbaik untuk mengingat!",
  ui_story_31030602_49_dialog_content = "Alun-alun kota... di malam hari...",
  ui_story_31030602_50_dialog_content = "Apakah Anda mencoba mengatakan bahwa pria ini muncul di alun-alun kota pada malam hari?",
  ui_story_31030602_51_dialog_content = "Agh...Nng...",
  ui_story_31030602_52_dialog_content = "Saya mengerti, saya mengerti! Terima kasih atas kerja sama anda!",
  ui_story_31030602_53_dialog_content = "Agh...Nng...",
  ui_story_31030602_54_dialog_content = "Ahhhh! M-mundur!",
  ui_story_31030602_55_dialog_content = "Oh, itu cukup untuk saat ini. Kamu bebas pergi.",
  ui_story_31030602_56_dialog_content = "Eicy, apa yang terjadi di sini?!",
  ui_story_31030602_57_dialog_content = "Ups! Maaf tentang itu, aku hampir melupakanmu. Terima kasih telah memberi saya kesaksian yang begitu penting!",
  ui_story_31030602_58_dialog_content = "Saksi? Maksudmu bukan monster?!",
  ui_story_31030602_59_dialog_content = "Seekor monster? Di mana? Bagaimana kakimu?",
  ui_story_31030602_60_dialog_content = "Tidak apa-apa, aku hanya tersandung batu tadi. Rasanya jauh lebih baik sekarang.",
  ui_story_31030602_61_dialog_content = "Jadi, apa yang kamu lakukan di sini?",
  ui_story_31030602_62_dialog_content = "Saya sedang menyelidiki—",
  ui_story_31030602_63_dialog_content = "Ada penjahat berkeliaran, manipulator pengetahuan yang juga membunuh banyak sarjana.",
  ui_story_31030602_64_dialog_content = "Tepat ketika saya sedang menginterogasinya, dia menggunakan sebuah buku misterius untuk lolos dari tahanan saya!",
  ui_story_31030602_65_dialog_content = "Jadi sekarang, aku memburunya!",
  ui_story_31030602_66_dialog_content = "Lalu apa yang salah dengan kota ini? Mengapa semua orang di sini begitu aneh?",
  ui_story_31030602_67_dialog_content = "Aneh, ya? Saya tidak melihat apa-apa, karena saya hanya tertarik pada penyelidikan saya.",
  ui_story_31030602_68_dialog_content = "Anda memberi tahu saya bahwa Anda baru saja tidak melihat sesuatu yang aneh tentang orang itu ?!",
  ui_story_31030602_69_dialog_content = "Ada yang salah dengan dia? Bukankah dia hanya warga kota biasa?",
  ui_story_31030602_70_dialog_content = "Itu, er... J-Lupakan saja. Saya tidak berpikir kita akan kemana-mana dengan diskusi ini.",
  ui_story_31030602_71_dialog_content = "Ngomong-ngomong, bisakah kau mengantarku kembali ke Soroz? Tempat ini terlalu berbahaya, dan hanya kamu yang bisa membantu!",
  ui_story_31030602_72_dialog_content = "Tidak bisa!",
  ui_story_31030602_73_dialog_content = "Tapi kenapa?!",
  ui_story_31030602_74_dialog_content = "Menemukan petunjuk tentang pembunuh ini tidaklah mudah. Prioritas utamaku sekarang adalah menangkap pria itu!",
  ui_story_31030602_75_dialog_content = "Namun…",
  ui_story_31030602_76_dialog_content = "Lagi pula, apa yang sangat kamu takutkan? Ini hanyalah kota biasa, Anda akan baik-baik saja sendiri!",
  ui_story_31030602_77_dialog_content = "Tidak ada yang biasa tentang itu!",
  ui_story_31030602_78_dialog_content = "Baiklah baiklah. Aku akan mengantarmu kembali setelah aku menyelesaikan pekerjaanku, oke?",
  ui_story_31030602_79_dialog_content = "Sigh, tebak itu berarti aku ikut juga.",
  ui_story_31030602_80_dialog_content = "Anda ingin ikut dengan saya? Apakah Anda tidak lupa bahwa saya adalah Interogator-slash-algojo terhebat di dunia? Anda hanya akan memperlambat saya!",
  ui_story_31030602_81_dialog_content = "Kalau begitu bawa saja aku kembali ke Soroz dulu!",
  ui_story_31030602_82_dialog_content = "Tidak, saya tidak punya waktu untuk itu.",
  ui_story_31030602_83_dialog_content = "Lalu aku ikut denganmu!!",
  ui_story_31030602_84_dialog_content = "Ugh ... lakukan dengan caramu. Seorang asisten mungkin berguna, saya kira.",
  ui_story_31030602_85_dialog_content = "Sudah larut, tapi masih belum ada tanda-tanda orang itu! Kapan dia akan muncul?!",
  ui_story_31030602_86_dialog_content = "Apakah kamu melihat itu, Eicy?",
  ui_story_31030602_87_dialog_content = "Melihat apa? Apakah itu dia?!",
  ui_story_31030602_88_dialog_content = "Tidak, tetapi semakin banyak orang muncul di sekitar sini.",
  ui_story_31030602_89_dialog_content = "Hah? Saya kira semua orang pasti suka nongkrong di alun-alun kota setelah gelap! Itu menjelaskan mengapa sangat sulit untuk menemukan orang ini.",
  ui_story_31030602_90_dialog_content = "Tapi mereka terlihat seperti sekelompok zombie!",
  ui_story_31030602_91_dialog_content = "Heehee, ini sempurna untuk penyelidikan saya! Salah satu dari mereka pasti memiliki kesaksian yang bermanfaat, jadi pertanyaannya dimulai!",
  ui_story_31030602_92_dialog_content = "Halo semuanya! Tolong temui saya untuk beberapa interogasi yang sangat penting!",
  ui_story_31030602_93_dialog_content = "Agh...Nng...",
  ui_story_31030602_94_dialog_content = "E-Eicy, mereka semua berjalan amburadul ke arah kita!",
  ui_story_31030602_95_dialog_content = "Tolong gali ingatan Anda yang paling dalam dan terabaikan, dan bantu saya menemukan pria misterius itu!",
  ui_story_31030602_96_dialog_content = "Hiss—",
  ui_story_31030602_97_dialog_content = "I-Penduduk kota semakin bermusuhan!",
  ui_story_31030602_98_dialog_content = "Mengaum-!",
  ui_story_31030602_99_dialog_content = "Dan sekarang mereka bertarung satu sama lain!",
  ui_story_31030602_100_dialog_content = "Ya, begitu saja! Telusuri sudut tergelap pikiran Anda, dan jangan tinggalkan satu detail pun!",
  ui_story_31030602_101_dialog_content = "Cukup, Eicy! Hentikan sekarang juga!",
  ui_story_31030602_102_dialog_content = "Argh, kau menghalangi pekerjaanku!",
  ui_story_31030602_103_dialog_content = "Katakan padaku, apakah kamu telah menggunakan kekuatanmu dengan sembrono selama kamu berada di sini?",
  ui_story_31030602_104_dialog_content = "Yup, dan itu karena targetku berusaha keras untuk menyembunyikan dirinya. Sebagai Interogator yang bangga, saya tidak boleh melewatkan satu petunjuk pun!",
  ui_story_31030602_105_dialog_content = "Mengaum-!",
  ui_story_31030602_106_dialog_content = "Sekarang bicara! Ceritakan padaku rahasia yang kau sembunyikan di hatimu!",
  ui_story_31030602_107_dialog_content = "(Nah, sekarang aku tahu kenapa seluruh kota seperti ini. Itu semua yang Eicy lakukan!)",
  ui_story_31030602_108_dialog_content = "(Dia membuat semua orang benar-benar gila, dan dia juga tidak menyerah—)",
  ui_story_31030602_109_dialog_content = "<size=50>Aaaaah!! Jangan sentuh aku!!</size>",
  ui_story_31030602_110_dialog_content = "Hmm? <size=45>Orang itu-</size>",
  ui_story_31030602_111_dialog_content = "(Dia mulai berteriak ketika penduduk kota yang merangkak mencengkeram pergelangan kakinya.)",
  ui_story_31030602_112_dialog_content = "(Itu berarti dia tidak kehilangan akal sehatnya seperti yang lainnya. Belum lagi benda yang ada di tangannya... <size=45>Apakah itu sebuah buku?!</size>)",
  ui_story_31030602_113_dialog_content = "Eicy, lihat pria di sana itu! Apakah orang yang Anda cari?",
  ui_story_31030602_114_dialog_content = "Itu dia! Tidak diragukan lagi!",
  ui_story_31030602_115_dialog_content = "Heeheehee! Jadi saya akhirnya menemukan Anda!",
  ui_story_31030602_116_dialog_content = "Lepaskan saya! Berangkat!",
  ui_story_31030602_117_dialog_content = "Anda yakin tidak membuatnya mudah! Jadi apa yang membuatmu bersembunyi dariku?",
  ui_story_31030602_118_dialog_content = "SS-Jauhi aku!",
  ui_story_31030602_119_dialog_content = "Mungkinkah itu buku milikmu? Ceritakan semua tentang itu, dan jangan lupa bagian di mana Anda menggunakannya untuk lolos dari jari saya!",
  ui_story_31030602_120_dialog_content = "Ahh! Menjauhlah dariku, kalian semua! Tidaaaak!",
  ui_story_31030602_121_dialog_content = "Beri tahu saya! Beri tahu aku semuanya!",
  ui_story_31030602_122_dialog_content = "Desis—raung—!",
  ui_story_31030602_123_dialog_content = "B-Tolong aku... <size=50>Seseorang bantu aku!!</size>",
  ui_story_31030602_124_dialog_content = "Kenapa tanganmu sangat gemetar? Hati-hati, atau Anda mungkin menjatuhkan buku berharga Anda!",
  ui_story_31030602_125_dialog_content = "Dan kenapa kau terlihat sangat ketakutan? Apakah karena semua orang ini?",
  ui_story_31030602_126_dialog_content = "Jangan khawatir, mereka hanya penduduk kota biasa!",
  ui_story_31030602_127_dialog_content = "<size=50>Monster!</size><size=45> Kalian semua adalah monster! </size>Ahh—",
  ui_story_31030602_128_dialog_content = "Dia kedinginan.",
  ui_story_31030602_129_dialog_content = "Untuk penjahat kelas kakap, dia sebenarnya cukup lemah. Saya berharap melihatnya menggunakan buku itu untuk melarikan diri lagi!",
  ui_story_31030602_130_dialog_content = "Ugh, bagaimana tepatnya cara kerja buku bodoh ini?!",
  ui_story_31030602_131_dialog_content = "Hai! Bangun, pengecut!",
  ui_story_31030602_132_dialog_content = "Aku tidak percaya dia pingsan! Apakah ini benar-benar pria yang saya kejar selama ini ?!",
  ui_story_31030602_133_dialog_content = "Ah, lupakan saja. Pekerjaan sudah selesai, jadi aku harus memberitahu yang lain untuk membereskan kekacauan ini.",
  ui_story_31030602_134_dialog_content = "Hah? Apa yang masih kalian lakukan di sini? Kalahkan, kalian semua!",
  ui_story_31030602_135_dialog_content = "...",
  ui_story_31030602_136_dialog_content = "(Saya tidak bisa berkata apa-apa karena terkejut dengan peristiwa hari itu.)",
  ui_story_31030602_137_dialog_content = "(Rasanya aku juga berubah menjadi zombie. Aku tidak tahu kapan atau bagaimana aku bisa keluar dari kota aneh itu...)",
  ui_story_31030602_138_dialog_content = "(Ketika saya membuka mata saya lagi, saya kembali ke kamar saya.)",
  ui_story_31030602_139_dialog_content = "(Saya tidak ingat kembali ke Soroz.)",
  ui_story_31030602_140_dialog_content = "(Apakah pengalaman saya di kota itu nyata? Atau apakah itu semua hanya mimpi buruk?)",
  ui_story_31030602_141_dialog_content = "(Kurasa itu tidak masalah. Aku harus mencuci muka untuk menjernihkan pikiranku sedikit.)",
  ui_story_31030602_142_dialog_content = "Selamat pagi, Caelestite kecilku yang imut!",
  ui_story_31030602_143_dialog_content = "Wow! A-Apa yang kau lakukan di kamarku?!",
  ui_story_31030602_144_dialog_content = "Untuk memberi tahu Anda kabar baik, tentu saja ...",
  ui_story_31030602_145_dialog_content = "Tunggu sebentar... Apakah kamu yang membawaku kembali kemarin?",
  ui_story_31030602_146_dialog_content = "Ya! Setelah saya selesai dengan penjahat itu, saya perhatikan Anda benar-benar terpana, jadi saya membawa Anda kembali.",
  ui_story_31030602_147_dialog_content = "Bagaimana dengan kota itu? Apakah orang-orang di sana akan menjadi zombie selamanya?",
  ui_story_31030602_148_dialog_content = "Apa yang Anda maksud dengan zombie? Rekan-rekan saya dan saya menghabiskan sepanjang malam berurusan dengan akibatnya, dan mereka tidak menyebutkan apa pun ...",
  ui_story_31030602_149_dialog_content = "Jadi tidak ada Interogator lain yang melihat sesuatu yang aneh? Mungkinkah mereka semua menjadi normal setelah Anda menyelesaikan interogasi Anda?",
  ui_story_31030602_150_dialog_content = "Jadi kota kembali damai, dan orang-orang miskin itu bisa kembali hidup bahagia. Senang mendengar!",
  ui_story_31030602_151_dialog_content = "Apa yang kamu bicarakan? Mereka semua pernah <size=45>ditangkap</size>!",
  ui_story_31030602_152_dialog_content = "A-Ditangkap?! Mereka semua?! Kenapa kau melakukan itu?!",
  ui_story_31030602_153_dialog_content = "Kota ini selalu menjadi tempat berkumpulnya para penjahat.",
  ui_story_31030602_154_dialog_content = "Karena lokasinya yang terpencil dan medan yang tidak dapat dilalui di sekitarnya, para penjahat sering berhasil lolos dari hukum dengan bersembunyi di tempat ini.",
  ui_story_31030602_155_dialog_content = "Tapi kali ini, saya berhasil menangani semuanya dalam satu gerakan!",
  ui_story_31030602_156_dialog_content = "Aku mengerti... Aku pikir aneh betapa agresifnya mereka. Kekuatanmu biasanya tidak memiliki efek seperti itu pada orang normal.",
  ui_story_31030602_157_dialog_content = "Tapi cukup tentang itu! Sudah kubilang aku punya kabar baik untuk dibagikan, bukan?",
  ui_story_31030602_158_dialog_content = "Untuk mengucapkan terima kasih karena telah membantuku menangkap penjahat bernilai tinggi itu, aku menyiapkan hadiah yang sangat spesial untukmu—",
  ui_story_31030602_159_dialog_content = "Selamat, PlayerName! Anda telah dipromosikan menjadi asisten saya!",
  ui_story_31030602_160_option_content = "Mengapa saya ingin menjadi asisten Anda ?!",
  ui_story_31030602_161_dialog_content = "Karena Anda telah mendapatkan persetujuan saya, yang membuat Anda lebih dari memenuhi syarat untuk pekerjaan itu!",
  ui_story_31030602_162_dialog_content = "Saya lebih suka tidak... Bolehkah saya menolak?",
  ui_story_31030602_163_dialog_content = "Menolak?! Tetapi jika Anda melakukan itu ...",
  ui_story_31030602_164_dialog_content = "Itu hanya akan membuatku semakin bersemangat!",
  ui_story_31030602_165_dialog_content = "Karena dengan begitu saya dapat mengunci Anda di ruang interogasi saya dan merusak tekad Anda setiap hari sampai Anda akhirnya mengatakan ya!",
  ui_story_31030602_166_dialog_content = "J-Jangan bercanda tentang hal seperti itu! Itu membuatku merinding!",
  ui_story_31030602_167_dialog_content = "Itu sebabnya Anda harus menerima tawaran saya!",
  ui_story_31030602_168_dialog_content = "...",
  ui_story_31030602_169_dialog_content = "Saya tidak mendengar kata tidak, jadi ayo pergi!",
  ui_story_31030602_170_option_content = "Apapun yang Anda katakan, Interogator Eicy.",
  ui_story_31030602_171_dialog_content = "Ha ha ha! Itu semangatnya, sekarang selesaikan cuci muka jadi kita sudah bisa berangkat!",
  ui_story_31030602_172_dialog_content = "Hah? Apa yang saya katakan?! Mengapa saya baru saja setuju dengan ini? Aku pasti setengah tertidur...",
  ui_story_31030602_173_dialog_content = "Kepalaku mulai terasa sedikit pusing. Saya yakin semuanya akan baik-baik saja setelah saya tidur.",
  ui_story_31030602_174_dialog_content = "Tidak akan ada yang tidur selama aku ada!",
  ui_story_31030602_175_dialog_content = "Ini hari baru, dan para tersangka tidak akan menginterogasi diri mereka sendiri! Ayo pergi.",
  ui_story_31030602_176_dialog_content = "Tidaaaak—"
